package dev.virtualesp32;

import android.Manifest;
import android.app.*;
import android.bluetooth.BluetoothAdapter;
import android.content.*;
import android.net.ConnectivityManager;
import android.net.NetworkCapabilities;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class MainActivity extends Activity {
    private VirtualHal hal; private LinearLayout root,body; private TextView state,logs,network,gpioState,gpio4State,uartState,nvsState,firmwareState; private Button power,ble;
    private static final int REQUEST_PERMISSION=40, CREATE_STATE=41, OPEN_STATE=42, NETWORK_PERMISSION=43, IMPORT_FIRMWARE=44;
    private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){refresh();}};
    @Override public void onCreate(Bundle b){super.onCreate(b);hal=VirtualHal.get(this);BridgeCommandReceiver.ensureBusListener(getApplicationContext());getWindow().setStatusBarColor(0xff101820);getWindow().setNavigationBarColor(0xff101820);build();IntentFilter f=new IntentFilter("dev.virtualesp32.STATE");if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,f);refresh();}
    @Override protected void onDestroy(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private void build(){
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(16),dp(18),dp(24));root.setBackgroundColor(0xff101820);scroll.addView(root);setContentView(scroll);
        TextView title=text("VIRTUAL ESP32",28,0xffffc857,true);root.addView(title);TextView subtitle=text("Android-hosted virtual device runtime",14,0xffb6c3ce,false);root.addView(subtitle);TextView bridge=text("BRIDGE SERVICE v2 - GHOST TAP IPC ready",13,0xff4caf50,true);bridge.setPadding(0,dp(4),0,dp(4));root.addView(bridge);state=text("Loading live device state…",13,0xffd9e2e9,false);state.setPadding(0,dp(10),0,dp(10));root.addView(state);
        panel("POWER / BOOT");LinearLayout row=new LinearLayout(this);power=button("Power"); /* D4: virtual-device power toggle only; powering off stops BLE, it does NOT touch the QEMU guest. */ ble=button("Start BLE");row.addView(power,new LinearLayout.LayoutParams(0,dp(48),1));row.addView(space(8));row.addView(ble,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(row);
        power.setOnClickListener(v->{boolean next=!hal.powered();hal.setPowered(next);if(!next)stop();else refresh();});
        ble.setOnClickListener(v->{if(hal.bleEnabled())stop();else ensurePermissionsAndStart();});
        panel("BLE");root.addView(text("Android BLE peripheral + GATT server. ESP-style endpoint names are exposed in descriptor 0x2901.",14,0xffd9e2e9,false));
        panel("NETWORK");network=text(networkSummary(),14,0xffd9e2e9,false);root.addView(network);Button networkPermission=button("Allow Android Wi-Fi scan access");root.addView(networkPermission);networkPermission.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.NEARBY_WIFI_DEVICES},NETWORK_PERMISSION);else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},NETWORK_PERMISSION);});
        panel("UART");uartState=text("",12,0xffa9e5c5,false);uartState.setTypeface(android.graphics.Typeface.MONOSPACE);root.addView(uartState);Button uart=button("Write to virtual UART");root.addView(uart);uart.setOnClickListener(v->input("UART TX","","Send",value->{String tx=value+"\n";if(FirmwareEmulatorRuntime.running()&&FirmwareEmulatorRuntime.writeUart(tx)){hal.log("UART","Sent to running guest UART");}else{hal.put("uart",(hal.get("uart","")+"\nTX: "+value).trim());hal.log("UART","Terminal-only TX (no guest connected)");}refresh();}));
        panel("GPIO");gpioState=text("",14,0xffd9e2e9,false);root.addView(gpioState);gpio4State=text("",14,0xffd9e2e9,false);root.addView(gpio4State);Button gpio=button("Toggle virtual GPIO 2");root.addView(gpio);gpio.setOnClickListener(v->{try{JSONObject j=new JSONObject(hal.get("gpio","{}"));boolean value=!j.optBoolean("2",false);j.put("2",value);hal.put("gpio",j.toString());hal.log("GPIO","GPIO2="+(value?"HIGH":"LOW"));refresh();}catch(Exception ignored){}});Button gpio4=button("Toggle guest GPIO4 input");root.addView(gpio4);gpio4.setOnClickListener(v->{try{JSONObject j=new JSONObject(hal.get("gpio","{}"));boolean value=!j.optBoolean("4in",false);j.put("4in",value);hal.put("gpio",j.toString());if(FirmwareEmulatorRuntime.running()){try{ClassicEsp32QemuBackend.nativeSetGpio4(value?1:0);hal.log("GPIO","HOST GPIO4 -> "+(value?"HIGH":"LOW"));}catch(Throwable t){hal.log("GPIO","HOST GPIO4 inject failed: "+t);}}else{hal.log("GPIO","GPIO4 input (no guest running)");}refresh();}catch(Exception ignored){}});
        root.addView(text("GPIO is virtual state only; Android exposes no general-purpose electrical pins.",12,0xff9baab6,false));
        panel("FLASH / NVS");nvsState=text("",14,0xffd9e2e9,false);root.addView(nvsState);Button nvs=button("Read / write virtual NVS");root.addView(nvs);nvs.setOnClickListener(v->input("NVS note (persistent)",readNvs(),value->{try{JSONObject j=new JSONObject(hal.get("nvs","{}"));j.put("note",value);hal.put("nvs",j.toString());hal.log("NVS","Persisted value");refresh();}catch(Exception ignored){}}));
        LinearLayout files=new LinearLayout(this);Button export=button("Export state"),imp=button("Import state");files.addView(export,new LinearLayout.LayoutParams(0,dp(48),1));files.addView(space(8));files.addView(imp,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(files);export.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"virtual-esp32-state.json");startActivityForResult(i,CREATE_STATE);});imp.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN_STATE);});
        panel("PROVISIONING");root.addView(text("Espressif provisioning v1.1 BLE endpoints are active. Security 0 (plaintext, no authentication) is supported; use a test network because credentials travel unencrypted. Wi-Fi credentials are persisted to virtual NVS. The virtual station reports connected only when the host phone is already on the same Wi-Fi SSID. Network scans return Android Wi-Fi observations when permission is granted. Security 1/2 and SoftAP transport are not implemented.",14,0xfff0d7a3,false));
        panel("FIRMWARE EMULATION · CLASSIC ESP32");firmwareState=text("",13,0xffd9e2e9,false);root.addView(firmwareState);LinearLayout firmwareButtons=new LinearLayout(this);Button importFirmware=button("Import merged ESP32 flash image"),runFirmware=button("Run firmware");firmwareButtons.addView(importFirmware,new LinearLayout.LayoutParams(0,dp(48),1));firmwareButtons.addView(space(8));firmwareButtons.addView(runFirmware,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(firmwareButtons);importFirmware.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_FIRMWARE);});runFirmware.setOnClickListener(v->runFirmware());LinearLayout guestControls=new LinearLayout(this);Button guestReset=button("Reset guest"),guestStop=button("Stop guest");guestControls.addView(guestReset,new LinearLayout.LayoutParams(0,dp(48),1));guestControls.addView(space(8));guestControls.addView(guestStop,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(guestControls);guestReset.setOnClickListener(v->{String r=FirmwareEmulatorRuntime.reset();if(!"ok".equals(r))new AlertDialog.Builder(this).setTitle("Guest reset failed").setMessage(r).setPositiveButton("OK",null).show();refresh();}); /* D4: SOFT reset (same QEMU session, guest CPU reset only) — NOT a restart; full restart is the receiver RESET_GUEST (stop+start). */ guestStop.setOnClickListener(v->{FirmwareEmulatorRuntime.stop();refresh();});
        panel("TIMERS / EVENTS");Button timer=button("Schedule a virtual timer event (5 seconds)");root.addView(timer);timer.setOnClickListener(v->{hal.log("TIMER","Timer scheduled for 5 seconds");new Handler().postDelayed(()->{hal.log("EVENT","Virtual timer fired");refresh();},5000);refresh();});
        panel("LOGS / TERMINAL");logs=text("",12,0xffa9e5c5,false);logs.setTypeface(android.graphics.Typeface.MONOSPACE);root.addView(logs);Button clear=button("Soft reset virtual runtime"); /* D4: hal.softReset() only (boot count + BLE restart); does NOT reset the QEMU guest. */ root.addView(clear);clear.setOnClickListener(v->{boolean wasOn=hal.powered();hal.softReset();if(wasOn){stop();new Handler().postDelayed(()->{if(hal.powered())start();},600);}refresh();});
        panel("BRIDGE DEBUG");Button bridgeLog=button("View bridge receiver log");root.addView(bridgeLog);bridgeLog.setOnClickListener(v->{try{java.io.File f=new java.io.File(getFilesDir(),"bridge_receiver.log");String content="No log yet - receiver never fired.";if(f.exists()){java.util.Scanner s=new java.util.Scanner(f).useDelimiter("\\Z");content=s.hasNext()?s.next():"(empty)";s.close();}new android.app.AlertDialog.Builder(this).setTitle("Bridge Receiver Log").setMessage(content).setPositiveButton("OK",null).show();}catch(Exception e){new android.app.AlertDialog.Builder(this).setTitle("Error").setMessage(e.toString()).setPositiveButton("OK",null).show();}});
    }
    private void panel(String name){TextView h=text(name,15,0xffffc857,true);h.setPadding(0,dp(22),0,dp(8));root.addView(h);}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);return t;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(0xff101820);b.setAllCaps(false);b.setTextSize(14);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffffc857));return b;}
    private View space(int w){View v=new View(this);v.setLayoutParams(new LinearLayout.LayoutParams(dp(w),1));return v;}
    private interface Value {void set(String value);}
    private void input(String title,String initial,Value v){input(title,initial,"Save",v);}
    private void input(String title,String initial,String okLabel,Value v){EditText e=new EditText(this);e.setText(initial);e.setSelection(e.getText().length());new AlertDialog.Builder(this).setTitle(title).setView(e).setPositiveButton(okLabel,(d,w)->v.set(e.getText().toString())).setNegativeButton("Cancel",null).show();}
    private String networkSummary(){try{ConnectivityManager c=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkCapabilities n=c.getNetworkCapabilities(c.getActiveNetwork());if(n==null)return "Phone network: offline. Android LocalOnlyHotspot is available, but this prototype does not start a SoftAP service.";String type=n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":n.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"cellular":n.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?"Ethernet":"other";return "Phone network: connected via "+type+". Android LocalOnlyHotspot can provide a managed local network; this prototype does not start a SoftAP service.";}catch(Exception e){return "Phone network: status unavailable";}}
    private String readNvs(){try{return new JSONObject(hal.get("nvs","{}")).optString("note","");}catch(Exception e){return "";}}
    private void ensurePermissionsAndStart(){if(Build.VERSION.SDK_INT>=31){String[] p={Manifest.permission.BLUETOOTH_ADVERTISE,Manifest.permission.BLUETOOTH_CONNECT};boolean ok=true;for(String x:p)ok&=checkSelfPermission(x)==android.content.pm.PackageManager.PERMISSION_GRANTED;if(!ok){requestPermissions(p,REQUEST_PERMISSION);return;}}start();}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQUEST_PERMISSION){boolean ok=true;for(int x:g)ok&=x==android.content.pm.PackageManager.PERMISSION_GRANTED;if(ok)ensurePermissionsAndStart();else{hal.log("BLE","Required Android permission not granted");refresh();}}else if(r==NETWORK_PERMISSION){boolean ok=true;for(int x:g)ok&=x==android.content.pm.PackageManager.PERMISSION_GRANTED;hal.log("NETWORK",ok?"Android Wi-Fi scan permission granted":"Android Wi-Fi scan permission denied");refresh();}}
    private void start(){Intent i=new Intent(this,VirtualDeviceService.class);i.setAction(VirtualDeviceService.ACTION_START);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
    private void stop(){Intent i=new Intent(this,VirtualDeviceService.class);i.setAction(VirtualDeviceService.ACTION_STOP);startService(i);}
    private void runFirmware(){String path=hal.get("firmwareImagePath","");if(path.isEmpty()){new AlertDialog.Builder(this).setMessage("Import and validate a merged ESP32 flash image first.").setPositiveButton("OK",null).show();return;}try{String result=FirmwareEmulatorRuntime.start(this,new File(path));if(!FirmwareEmulatorRuntime.running())new AlertDialog.Builder(this).setTitle("Firmware was not started").setMessage(result).setPositiveButton("OK",null).show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Firmware was not started").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}refresh();}
    private void refresh(){if(state==null)return;if(network!=null)network.setText(networkSummary());if(gpioState!=null){try{JSONObject g=new JSONObject(hal.get("gpio","{}"));boolean guest=g.optBoolean("guest_driven",false);gpioState.setText("GPIO 2: "+(g.optBoolean("2",false)?"HIGH":"LOW")+(guest?" (guest-driven)":" (virtual state only)"));}catch(Exception ignored){}}if(gpio4State!=null){try{JSONObject g=new JSONObject(hal.get("gpio","{}"));gpio4State.setText("GPIO 4 INPUT: "+(g.optBoolean("4in",false)?"HIGH":"LOW")+" (host-injected)");}catch(Exception ignored){}}if(uartState!=null){String u=hal.get("uart","");uartState.setText(u.length()>1500?u.substring(u.length()-1500):u);}if(nvsState!=null)nvsState.setText("Wi-Fi SSID: "+hal.get("wifiSsid","(none)")+" · "+(hal.get("wifiConfigured","false").equals("true")?"credentials stored":"not configured")+"\nNVS note: "+readNvs());if(firmwareState!=null){String img=hal.get("firmwareImageSummary","");firmwareState.setText((img.isEmpty()?"No firmware image imported.\n":img+"\n")+FirmwareEmulatorRuntime.backendAvailability()+"\nRuntime: "+FirmwareEmulatorRuntime.status()+". Firmware execution is reported running only after a native QEMU machine is created.");}state.setText("POWER: "+(hal.powered()?"ON":"OFF")+"    BLE: "+(hal.bleEnabled()?"ON":"OFF")+"\nBoot count: "+hal.bootCount()+"\nDevice: "+hal.deviceName()+"\nProvisioning: Security 0 (plaintext) · "+(hal.get("wifiConfigured","false").equals("true")?"Wi-Fi credentials stored":"not configured")+"\nService UUID: 7ab1ffff-6b3d-4f60-9e2f-13572468f00d\nPhone: "+Build.MANUFACTURER+" "+Build.MODEL+" · Android "+Build.VERSION.RELEASE);
        if(power!=null)power.setText(hal.powered()?"Power off":"Power on");if(ble!=null)ble.setText(hal.bleEnabled()?"Stop BLE":"Start BLE");if(logs!=null){StringBuilder b=new StringBuilder();JSONArray a=hal.logs();for(int n=Math.max(0,a.length()-35);n<a.length();n++){JSONObject x=a.optJSONObject(n);if(x!=null)b.append(x.optString("time")).append(" ").append(x.optString("tag")).append("  ").append(x.optString("message")).append('\n');}logs.setText(b.toString());}}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;try{if(r==IMPORT_FIRMWARE){FirmwareImageManager.Inspection x=FirmwareImageManager.importAndInspect(this,data.getData());if(x.valid){hal.put("firmwareImagePath",x.image.getAbsolutePath());hal.put("firmwareImageSummary",x.summary);hal.log("EMU",x.summary+"; imported only, not executed");}else hal.log("EMU","Image rejected: "+x.summary);new AlertDialog.Builder(this).setTitle(x.valid?"Merged image imported":"Image rejected").setMessage(x.summary+(x.valid?"\n"+FirmwareEmulatorRuntime.backendAvailability():"")).setPositiveButton("OK",null).show();}else if(r==CREATE_STATE){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(hal.exportState().toString(2).getBytes(StandardCharsets.UTF_8));}hal.log("FLASH","Exported virtual state");}else if(r==OPEN_STATE){try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);hal.importState(new JSONObject(out.toString("UTF-8")));}}refresh();}catch(Exception e){new AlertDialog.Builder(this).setMessage("File error: "+e.getMessage()).setPositiveButton("OK",null).show();}}
}
